function validate([timeReq, splitTime]) {
  if (timeReq.length < 2 || timeReq.length > 100000) return 'timeReq needs 2 to 10^5 values.';
  if (timeReq.some(t => t < 1 || t > 1000000000)) return 'Each value in timeReq is between 1 and 10^9.';
  if (splitTime < 1 || splitTime > 1000000000) return 'splitTime is between 1 and 10^9.';
  return null;
}

