function minEliminationTime(timeReq, splitTime) {
  const heap = [];
  function push(value) {
    heap.push(value);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent] <= heap[child]) {
        break;
      }
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  }
  function pop() {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let parent = 0;
      while (2 * parent + 1 < heap.length) {
        let child = 2 * parent + 1;
        if (child + 1 < heap.length && heap[child + 1] < heap[child]) {
          child++;
        }
        if (heap[parent] <= heap[child]) {
          break;
        }
        [heap[parent], heap[child]] = [heap[child], heap[parent]];
        parent = child;
      }
    }
    return top;
  }
  for (const time of timeReq) {
    push(time);
  }
  // The two quickest jobs go to the two halves of one split, which then acts as a single job.
  while (heap.length > 1) {
    const first = pop();
    const second = pop();
    push(splitTime + Math.max(first, second));
  }
  return heap[0];
}

