function minEliminationTime(timeReq, splitTime) {
  // fastest[mask]: least time for one cell to clear exactly the strains in mask (for small inputs).
  const n = timeReq.length;
  const fastest = new Array(1 << n).fill(Infinity);
  for (let mask = 1; mask < 1 << n; mask++) {
    if ((mask & (mask - 1)) === 0) {
      fastest[mask] = timeReq[31 - Math.clz32(mask)];
      continue;
    }
    // Two or more strains: the cell must split, and its halves divide the strains between them.
    const lowest = mask & -mask;
    for (let part = (mask - 1) & mask; part > 0; part = (part - 1) & mask) {
      if ((part & lowest) === 0) continue;
      fastest[mask] = Math.min(fastest[mask], splitTime + Math.max(fastest[part], fastest[mask ^ part]));
    }
  }
  return fastest[(1 << n) - 1];
}

