function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 8);
  const top = pick(size === 'large' ? [10, 1000000, 1000000000] : [3, 20, 1000, 1000000000]);
  const timeReq = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Sometimes one strain is far slower than the rest, so it should split off at the very top.
  if (rand() < 0.25) timeReq[Math.floor(rand() * n)] = 1000000000;
  const splitTime = 1 + Math.floor(rand() * pick([3, 50, 1000000, 1000000000]));
  return [timeReq, splitTime];
}
